import{_ as e,o,c as a,a5 as r}from"./chunks/framework.a5no_H3L.js";const u=JSON.parse('{"title":"网络 IO 的生产实践","description":"本页面向已经能用 requests / httpx 发请求、想搞清楚\\"生产环境里大家到底怎么选、怎么配\\"的读者，回答一个问题：把 HTTP 客户端放进真实服务后，选库、连接池、超时重试和生命周期分别该按什么原则定。前置知识是 HTTP 客户端基础和 HTTP 客户端进阶。","frontmatter":{"type":"explanation","level":"intermediate"},"headers":[],"relativePath":"python/03-python-network/chapter-06-production-practices.md","filePath":"python/03-python-network/chapter-06-production-practices.md"}'),c={name:"python/03-python-network/chapter-06-production-practices.md"};function n(p,t,d,i,s,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="网络-io-的生产实践" tabindex="-1" data-src-line="2" data-src-file="python/03-python-network/chapter-06-production-practices.md">网络 IO 的生产实践 <a class="header-anchor" href="#网络-io-的生产实践" aria-label="Permalink to &quot;网络 IO 的生产实践&quot;">​</a></h1><p data-src-line="4" data-src-file="python/03-python-network/chapter-06-production-practices.md">本页面向已经能用 requests / httpx 发请求、想搞清楚&quot;生产环境里大家到底怎么选、怎么配&quot;的读者，回答一个问题：把 HTTP 客户端放进真实服务后，选库、连接池、超时重试和生命周期分别该按什么原则定。前置知识是 <a href="./chapter-01-http-client.html">HTTP 客户端基础</a>和 <a href="./chapter-04-http-advanced.html">HTTP 客户端进阶</a>。</p><p data-src-line="6" data-src-file="python/03-python-network/chapter-06-production-practices.md">示例基于 requests 2.x、httpx 0.28、aiohttp 3.14 和 Python 3.13+。</p><h2 id="_1-怎么选库" tabindex="-1" data-src-line="8" data-src-file="python/03-python-network/chapter-06-production-practices.md">1. 怎么选库 <a class="header-anchor" href="#_1-怎么选库" aria-label="Permalink to &quot;1. 怎么选库&quot;">​</a></h2><p data-src-line="10" data-src-file="python/03-python-network/chapter-06-production-practices.md">选库先看代码运行在同步还是异步上下文，再看是否需要 HTTP/2：</p><ul data-src-line="12" data-src-file="python/03-python-network/chapter-06-production-practices.md"><li data-src-line="12" data-src-file="python/03-python-network/chapter-06-production-practices.md"><strong>同步代码</strong>：<code>requests</code> 仍是事实标准，接口最简单、生态最全。它默认每个主机最多复用 10 条连接（<code>pool_maxsize=10</code>）。</li><li data-src-line="13" data-src-file="python/03-python-network/chapter-06-production-practices.md"><strong>异步代码</strong>：<code>httpx</code> 提供和 requests 几乎一致的接口，同步异步一套 API，还支持 HTTP/2（<code>http2=True</code>）；<code>aiohttp</code> 是纯异步实现，性能更好、也是 FastAPI 底层的依赖，但 API 和同步库差异大、学起来更重。</li><li data-src-line="14" data-src-file="python/03-python-network/chapter-06-production-practices.md"><strong>需要 HTTP/2</strong>：用 <code>httpx</code> 开启 <code>http2=True</code>；<code>requests</code> 不支持。</li></ul><p data-src-line="16" data-src-file="python/03-python-network/chapter-06-production-practices.md">原则是<strong>一个服务里尽量只用一种客户端</strong>，避免同一套超时、重试、鉴权逻辑要在两套 API 里维护两遍。异步服务里混入 <code>requests</code> 会阻塞事件循环，这是<a href="./../01-python-language/chapter-11-asyncio.html">异步章节</a>反复强调的坑。</p><h2 id="_2-连接池大小按并发量配" tabindex="-1" data-src-line="18" data-src-file="python/03-python-network/chapter-06-production-practices.md">2. 连接池大小按并发量配 <a class="header-anchor" href="#_2-连接池大小按并发量配" aria-label="Permalink to &quot;2. 连接池大小按并发量配&quot;">​</a></h2><p data-src-line="20" data-src-file="python/03-python-network/chapter-06-production-practices.md">连接池决定了&quot;同时能有多少条到下游的连接&quot;。默认值只是起点：<code>requests</code> 是 10，<code>httpx</code> 是 100。</p><p data-src-line="22" data-src-file="python/03-python-network/chapter-06-production-practices.md">配置时看两个数：你的服务<strong>同时会发多少个请求</strong>，以及<strong>下游能承受多少连接</strong>。池子小于并发请求数，请求会排队等连接，等不到就超时；池子远大于实际并发，等于白占下游和你本机的连接、端口和内存。实践中先量出峰值并发，再让池子上限略高于它，并观察下游的连接数和本机端口占用做微调，而不是拍一个&quot;大一点更好&quot;的数。</p><h2 id="_3-超时和重试要区分场景" tabindex="-1" data-src-line="24" data-src-file="python/03-python-network/chapter-06-production-practices.md">3. 超时和重试要区分场景 <a class="header-anchor" href="#_3-超时和重试要区分场景" aria-label="Permalink to &quot;3. 超时和重试要区分场景&quot;">​</a></h2><p data-src-line="26" data-src-file="python/03-python-network/chapter-06-production-practices.md">超时里最关键的是把&quot;连不上&quot;和&quot;响应慢&quot;分开：连接超时设短（几秒），让网络不通快速失败；读取超时按接口真实耗时设，慢接口和下载要放宽。所有请求都要显式设超时——<code>requests</code> 默认超时是 <code>None</code>，也就是<strong>无限等</strong>，一个挂起的下游能拖垮整个调用链。</p><p data-src-line="28" data-src-file="python/03-python-network/chapter-06-production-practices.md">重试只对<strong>幂等</strong>操作（GET、以及明确幂等的接口）开启，并且要限制次数和退避。写操作重复执行可能产生副作用（重复下单、重复扣款），所以 POST/PUT 默认不重试。重试还要带指数退避，避免故障时所有调用方同时重试、把下游压成雪崩。</p><h2 id="_4-client-要复用-退出要优雅" tabindex="-1" data-src-line="30" data-src-file="python/03-python-network/chapter-06-production-practices.md">4. client 要复用，退出要优雅 <a class="header-anchor" href="#_4-client-要复用-退出要优雅" aria-label="Permalink to &quot;4. client 要复用，退出要优雅&quot;">​</a></h2><p data-src-line="32" data-src-file="python/03-python-network/chapter-06-production-practices.md">连接池的价值来自复用，所以 client 应该作为长期对象存在：Web 服务在启动时创建一个全局 client，进程退出时关闭，而不是每请求新建。请求间共享的还有 TLS 会话和 DNS 缓存，新建即弃等于每次都重新握手、重新解析。</p><p data-src-line="34" data-src-file="python/03-python-network/chapter-06-production-practices.md">关闭也要优雅：<code>httpx</code> 用 <code>await client.aclose()</code> 或 <code>async with</code>，<code>requests</code> 用 <code>session.close()</code>。直接让进程退出或不管 client，连接池里已经建立的 TCP 连接可能来不及正常关闭，造成对端短暂的连接重置。</p><h2 id="_5-常见坑" tabindex="-1" data-src-line="36" data-src-file="python/03-python-network/chapter-06-production-practices.md">5. 常见坑 <a class="header-anchor" href="#_5-常见坑" aria-label="Permalink to &quot;5. 常见坑&quot;">​</a></h2><ul data-src-line="38" data-src-file="python/03-python-network/chapter-06-production-practices.md"><li data-src-line="38" data-src-file="python/03-python-network/chapter-06-production-practices.md"><strong>在异步代码里用同步客户端</strong>：<code>requests</code> 的调用会阻塞事件循环，导致所有协程一起卡住。异步服务里 IO 必须用异步库。</li><li data-src-line="39" data-src-file="python/03-python-network/chapter-06-production-practices.md"><strong>连接泄漏</strong>：每次请求新建 client 且不关闭，或 <code>stream</code> 响应没有读完就丢弃，连接不会被归还池子，慢慢把文件描述符和端口耗尽。</li><li data-src-line="40" data-src-file="python/03-python-network/chapter-06-production-practices.md"><strong>忘了设超时</strong>：默认无超时（<code>requests</code>）或默认 5 秒（<code>httpx</code>）都不等于&quot;适合你的下游&quot;，一定要显式设。</li><li data-src-line="41" data-src-file="python/03-python-network/chapter-06-production-practices.md"><strong>重试非幂等请求</strong>：把 POST 放进重试列表，等于默认允许重复执行写操作。</li><li data-src-line="42" data-src-file="python/03-python-network/chapter-06-production-practices.md"><strong>DNS 解析耗时</strong>：同步 <code>requests</code> 在高频调用时，DNS 解析会成为固定开销，复用 <code>Session</code> 能缓解；异步栈里一般由事件循环和底层库处理，但自建服务时仍要留意。</li></ul><h2 id="_6-这一章要记住的结论" tabindex="-1" data-src-line="44" data-src-file="python/03-python-network/chapter-06-production-practices.md">6. 这一章要记住的结论 <a class="header-anchor" href="#_6-这一章要记住的结论" aria-label="Permalink to &quot;6. 这一章要记住的结论&quot;">​</a></h2><p data-src-line="46" data-src-file="python/03-python-network/chapter-06-production-practices.md">同步用 <code>requests</code>、异步用 <code>httpx</code> 或 <code>aiohttp</code>，一个服务尽量只用一种；连接池按实际并发量配，超时区分连接和读取，重试只对幂等操作且带退避；client 作为长期对象复用并在退出时优雅关闭，避免连接泄漏和阻塞事件循环。</p><p data-src-line="48" data-src-file="python/03-python-network/chapter-06-production-practices.md">接下来进入 <a href="./../04-fastapi/chapter-01-fastapi-core.html">FastAPI 后端开发</a>，把视角从&quot;调用方&quot;转到&quot;提供方&quot;，看怎么用 FastAPI 搭带校验和依赖注入的接口。</p>',21)])])}const y=e(c,[["render",n]]);export{u as __pageData,y as default};
